export const roleNames={admin:'مدير العائلة',journalist:'صحفي',auditor:'مدقق',member:'عضو'};
export const roleLabel=roles=>(roles||[]).filter(r=>r!=='member'||roles.length===1).map(r=>roleNames[r]||r).join(' · ');
export function initCommunityHub(c){const{state,req,element:E,button:B,busy,toast}=c;const call=(action,payload={})=>req('/rest/v1/rpc/community_hub',{method:'POST',body:{action,payload}});let self={},epoch=0;
 function dialog(title){const d=E('dialog',undefined,'community-hub-dialog'),h=E('header');h.append(E('h2',title),B('إغلاق',()=>{d.close();d.remove()},'text-button'));d.append(h);document.body.append(d);d.showModal();return d}
 function person(p){const b=B(p.display_name,()=>document.dispatchEvent(new CustomEvent('family:member',{detail:{id:p.id}})),'text-button');return b}
 const search=B('البحث عن عضو ومتابعته',()=>busy(search,openSearch),'text-button'),square=B('الساحة الحرة',()=>busy(square,openSquare),'text-button'),team=B('إدارة الكيان العائلي',()=>busy(team,openTeam),'text-button'),review=B('طلبات التفعيل',()=>busy(review,openReview),'text-button');for(const b of[search,square,team,review]){b.hidden=true;document.querySelector('.app-nav').append(b)}
 async function openSearch(){const d=dialog('البحث عن الأعضاء ومتابعتهم'),input=E('input'),list=E('div');input.placeholder='ابحث بالاسم من أول حرف…';input.setAttribute('aria-label','اسم العضو');d.append(input,list);let timer,seq=0;input.oninput=()=>{clearTimeout(timer);const n=++seq,term=input.value.trim();list.replaceChildren();if(!term)return;timer=setTimeout(()=>busy(input,async()=>{const rows=await call('search',{term});if(n!==seq||!d.open)return;list.replaceChildren();for(const p of rows){const row=E('article',undefined,'hub-person');row.append(person(p),E('small',roleLabel(p.roles)));if(p.id!==state.user.id){const follow=B(p.following?'تتابعه ✓':'متابعة',()=>busy(follow,async()=>{const data=await req('/rest/v1/rpc/member_social',{method:'POST',body:{action:p.following?'unfollow':'follow',payload:{member:p.id}}});p.following=data.following;follow.textContent=p.following?'تتابعه ✓':'متابعة'}),'secondary');follow.disabled=!!state.readOnly;row.append(follow)}list.append(row)}if(!rows.length)list.append(E('p','لا توجد نتائج.'))}),250)};d.addEventListener('close',()=>{seq++;clearTimeout(timer)});input.focus()}
 async function openTeam(){const d=dialog('إدارة الكيان العائلي'),rows=await call('team');if(!d.open)return;for(const p of rows){const row=E('article',undefined,'hub-person');row.append(person(p),E('p',roleLabel(p.roles)));d.append(row)}if(!rows.length)d.append(E('p','لم يحدد فريق الإدارة بعد.'))}
 async function openReview(){const d=dialog('طلبات تفعيل الأعضاء'),box=E('div');d.append(box);async function load(){const rows=await call('pending');box.replaceChildren();for(const p of rows){const row=E('article',undefined,'hub-person');row.append(E('h3',p.display_name),E('p',p.email+(p.email_confirmed?' · البريد مؤكد':' · ينتظر تأكيد البريد')),E('p','الجنس: '+({male:'ذكر',female:'أنثى'}[p.gender]||'غير محدد')),E('p','المعرّف: '+(p.reference_name||'—')+' · '+(p.relationship||'—')));const activate=B('اعتماد وتفعيل العضو',()=>busy(activate,async()=>{await call('activate',{member:p.id});await load();await refresh();toast('تم تفعيل العضو.')}),'primary');activate.disabled=!!state.readOnly||!p.email_confirmed;row.append(activate);box.append(row)}if(!rows.length)box.append(E('p','لا توجد طلبات تفعيل.'))}await load()}
 async function openSquare(){const d=dialog('الساحة الحرة'),composer=E('form'),text=E('textarea'),send=E('button','نشر','primary'),feed=E('div'),more=B('منشورات أقدم',()=>busy(more,()=>load(false)),'secondary');text.required=true;text.maxLength=5000;text.rows=4;text.placeholder='شارك فكرة أو افتح نقاشًا مع العائلة…';send.disabled=!!state.readOnly;composer.append(text,send);d.append(composer,feed,more);let before=null,loading=false;composer.onsubmit=e=>{e.preventDefault();busy(send,async()=>{await call('publish',{body:text.value});text.value='';await load(true)})};async function load(reset){if(loading)return;loading=true;try{const rows=await call('feed',reset?{}:{before});if(!d.open)return;if(reset)feed.replaceChildren();for(const p of rows)feed.append(card(p));before=rows.at(-1)?.id||before;more.hidden=rows.length<30;if(!feed.children.length)feed.append(E('p','ابدأ أول نقاش في الساحة.'))}finally{loading=false}}function card(p){const article=E('article',undefined,'square-post'),header=E('header');header.append(person(p),E('small',new Date(p.created_at).toLocaleString('ar-SA')));article.append(header,E('p',p.body,'square-body'));if(state.profile.role==='admin'||p.author_id===state.user.id)article.append(B('حذف المنشور',()=>busy(null,async()=>{if(!confirm('حذف المنشور وتعليقاته؟'))return;await call('delete',{post:p.id});await load(true)}),'text-button danger'));const reactions=E('div',undefined,'square-reactions');for(const emoji of['👍','❤️','😂','😮','😢','🙏']){const b=B(emoji+' '+(p.reactions?.[emoji]||''),()=>busy(b,async()=>{await call('react',{post:p.id,emoji:p.my_reaction===emoji?'':emoji});await load(true)}),'secondary');b.setAttribute('aria-pressed',String(p.my_reaction===emoji));b.disabled=!!state.readOnly;reactions.append(b)}const details=E('details'),summary=E('summary','التعليقات · '+p.comments),comments=E('div'),next=B('تعليقات أخرى',()=>busy(next,()=>readComments(false)),'secondary');let last=0;details.append(summary,comments,next);details.ontoggle=()=>{if(details.open)busy(summary,()=>readComments(true))};async function readComments(reset){const rows=await call('comments',{post:p.id,after:reset?0:last});if(reset)comments.replaceChildren();for(const row of rows){const box=E('article',undefined,'square-comment');box.append(person(row),E('p',row.body,'square-body'));if(state.profile.role==='admin'||row.author_id===state.user.id)box.append(B('حذف',()=>busy(null,async()=>{await call('comment_delete',{post:p.id,comment:row.id});await readComments(true)}),'text-button danger'));comments.append(box)}last=rows.at(-1)?.id||last;next.hidden=rows.length<100}const f=E('form'),input=E('textarea'),submit=E('button','تعليق','secondary');input.required=true;input.maxLength=2000;input.rows=2;input.placeholder='اكتب تعليقك…';submit.disabled=!!state.readOnly;f.append(input,submit);f.onsubmit=e=>{e.preventDefault();busy(submit,async()=>{await call('comment',{post:p.id,body:input.value});input.value='';summary.textContent='التعليقات · '+(++p.comments);await readComments(true)})};details.append(f);article.append(reactions,details);return article}await load(true)}
 const birth=E('form');birth.id='birth-profile-form';const label=E('label','تاريخ الميلاد'),date=E('input'),visible=E('input'),vlabel=E('label','إظهار تاريخ الميلاد لأعضاء العائلة','inline');date.type='date';date.min='1900-01-01';date.max=new Date().toISOString().slice(0,10);visible.type='checkbox';label.append(date);vlabel.prepend(visible);birth.append(E('h3','الميلاد والصلاحيات'),label,vlabel,E('p','يمكنك إخفاؤه عن الأعضاء. مدير العائلة يستطيع الاطلاع عليه.','muted'));const badges=E('p'),save=E('button','حفظ تاريخ الميلاد','secondary');birth.append(badges,save);document.getElementById('profile-dialog').append(birth);birth.onsubmit=e=>{e.preventDefault();busy(save,async()=>{await call('birth_save',{birth_date:date.value||null,visible:visible.checked});toast('حُفظ تاريخ الميلاد وخيار الخصوصية.')})};const observer=new window.MutationObserver(()=>{if(document.getElementById('profile-dialog').open&&state.user)loadOwn().catch(e=>toast(e.message))});observer.observe(document.getElementById('profile-dialog'),{attributes:true,attributeFilter:['open']});async function loadOwn(){const s=await call('self');date.value=s.birth_date||'';visible.checked=!!s.birth_visible;badges.textContent=roleLabel(s.roles);save.disabled=!!state.readOnly}
 const control=E('label','تشغيل الساحة الحرة لجميع الأعضاء','inline'),toggle=E('input');toggle.type='checkbox';control.prepend(toggle);control.hidden=true;document.getElementById('settings-section').append(control);toggle.onchange=()=>busy(toggle,async()=>{await call('enable',{enabled:toggle.checked});await refresh();toast('حُفظ إعداد الساحة الحرة.')});async function refresh(){const n=++epoch;if(!state.user){reset();return}self=await call('self');if(n!==epoch)return;const active=state.profile?.status==='active';search.hidden=team.hidden=!active;square.hidden=!active||!self.enabled;review.hidden=!self.reviewer;review.textContent='طلبات التفعيل'+(self.pending?' · '+self.pending:'');control.hidden=state.profile?.role!=='admin';toggle.checked=!!self.enabled;toggle.disabled=!!state.readOnly;if(!self.enabled)document.querySelectorAll('.community-hub-dialog').forEach(d=>{if(d.querySelector('.square-post')||d.querySelector('textarea[maxlength="5000"]')){d.close();d.remove()}})}function reset(){epoch++;for(const b of[search,square,team,review])b.hidden=true;control.hidden=true;date.value='';badges.textContent='';document.querySelectorAll('.community-hub-dialog').forEach(d=>d.remove())}const timer=setInterval(()=>{if(state.user&&!document.hidden)refresh().catch(()=>{})},30000);timer.unref?.();return{refresh,reset}}
